  function applyThemeToStatusBars(theme) {
    const payload = { type: 'fjb-set-theme', theme: theme };
    let origin = '*';
    try { origin = window.location.origin || '*'; } catch (_) {}
    try { window.postMessage(payload, origin); } catch (_) {}
    try { hostWindow().postMessage(payload, origin); } catch (_) {}
    const themeVars = getThemeVars(theme);
    const docs = [document];
    try { if (hostWindow().document) docs.push(hostWindow().document); } catch (_) {}
    docs.forEach(doc => {
      // 1. 更新所有状态栏 iframe
      const iframes = doc.querySelectorAll('[data-fjb-status-iframe]');
      for (let i = 0; i < iframes.length; i++) {
        try { iframes[i].contentWindow.postMessage(payload, '*'); } catch (_) {}
      }
      // 2. 更新 HUD iframe
      if (hudSession.iframe) {
        try { hudSession.iframe.contentWindow.postMessage(payload, '*'); } catch (_) {}
      }
      // 3. 更新开局页 iframe
      const openingIframes = doc.querySelectorAll('[data-fjb-opening-iframe]');
      for (let i = 0; i < openingIframes.length; i++) {
        try { openingIframes[i].contentWindow.postMessage(payload, '*'); } catch (_) {}
      }
      // 4. 更新老式状态栏根节点 CSS 变量
      const roots = doc.querySelectorAll('#sb-root, .sb');
      for (let j = 0; j < roots.length; j++) {
        const el = roots[j];
        Object.keys(themeVars).forEach(k => el.style.setProperty(k, themeVars[k]));
      }
      // 5. ★ 更新 HUD 面板本身（#fjb-hud-panel）的背景色，使其随主题切换 ★
      const hudPanelEl = doc.getElementById(HUD_PANEL_ID);
      if (hudPanelEl) {
        // 根据主题设置 HUD 面板背景（粉色=浅粉磨砂，紫色/深色=深色磨砂）
        const bgMap = {
          pink: 'rgba(255,182,193,.32)',
          purple: 'rgba(45,27,61,.65)',
          dark: 'rgba(26,26,46,.72)',
        };
        hudPanelEl.style.background = bgMap[theme] || bgMap.pink;
        // 同时更新 HUD 面板的 CSS 变量（供子元素使用）
        Object.keys(themeVars).forEach(k => hudPanelEl.style.setProperty(k, themeVars[k]));
      }
      // 6. ★ 更新控制中心面板本身（#fjb-cc-panel）的背景色 ★
      const ccPanelEl = doc.getElementById(PANEL_ID);
      if (ccPanelEl) {
        const panelDiv = ccPanelEl.querySelector('div');
        if (panelDiv) {
          panelDiv.style.background = themeVars['--c-bg'];
          panelDiv.style.color = themeVars['--c-text'];
        }
      }
    });
  }

