  // ========================================================================
  // 第二十章 事件系统（13+ 事件，对齐星酒 GENERATION_ENDED 等）
  // ========================================================================
  function registerTavernEvents() {
    try {
      const host = hostWindow();
      const eventOnFn = (typeof eventOn === 'function') ? eventOn :
                        (window.eventOn) ? window.eventOn :
                        (host.eventOn) ? host.eventOn : null;
      if (!eventOnFn) { console.warn('[假阴茎卡] eventOn 不可用'); return; }
      // 优先用 tavern_events 枚举字段（避免硬编码字符串，对齐星月）
      const ev = window.tavern_events || host.tavern_events || {};
      // 自动推送 stat_data + 重新注入
      const autoPush = () => {
        setTimeout(() => {
          pushStatDataToStatusBars();
          injectStatusBars().then(() => setTimeout(pushStatDataToStatusBars, 500));
          injectOpeningPages();
          injectOmniUI();
        }, 800);
      };
      // 用枚举字段注册事件（对齐星月 bindHudDataEvents 写法）
      const eventList = [
        ev.GENERATION_ENDED, ev.MESSAGE_EDITED, ev.MESSAGE_SWIPED,
        ev.MESSAGE_RECEIVED, ev.MESSAGE_UPDATED, ev.CHAT_CHANGED,
        ev.CHAT_LOADED, ev.CHAT_CREATED,
        ev.MESSAGE_SENT, ev.MESSAGE_DELETED,
        ev.CHARACTER_CHANGED, ev.APP_READY,
        ev.GENERATION_AFTER_COMMANDS, ev.GENERATE_BEFORE_COMBINE_PROMPTS,
        ev.CHAT_COMPLETION_PROMPT_READY,
      ].filter(Boolean);
      // 兼容 MVU 事件（mag_variable_update_ended 是字符串常量）
      const mvuEvents = ['mag_variable_update_ended', 'generation_started'];
      eventList.forEach(name => {
        try { const d = eventOnFn(name, autoPush); if (d && d.stop) addDisposer(() => d.stop()); } catch (_) {}
      });
      mvuEvents.forEach(name => {
        try { const d = eventOnFn(name, autoPush); if (d && d.stop) addDisposer(() => d.stop()); } catch (_) {}
      });
      console.log('[假阴茎卡] 事件系统已注册 (' + (eventList.length + mvuEvents.length) + ' 事件)');
    } catch (e) {
      console.warn('[假阴茎卡] 注册事件监听失败:', e.message);
    }
  }

  // ========================================================================
  // 第二十一章 postMessage 监听（老式状态栏兼容通道 + 开局页通信）
  // ========================================================================
  // 应用开局页草稿到 MVU 变量
  async function applyOpeningDraft(draft) {
    if (!draft || typeof draft !== 'object') {
      console.warn('[假阴茎卡] applyOpeningDraft: draft 为空');
      return false;
    }
    try {
      const nextData = await hudUpdateVariablesWith((data) => {
        if (!data || !data.stat_data) data = { stat_data: {} };
        const s = data.stat_data;
        // basic 字段
        if (!s.basic) s.basic = {};
        if (draft.player_callname) s.basic.name = String(draft.player_callname);
        if (draft.player_background) s.basic.background = String(draft.player_background);
        if (draft.player_appearance) s.basic.appearance = String(draft.player_appearance);
        if (draft.player_skills) s.basic.skills_desc = String(draft.player_skills);
        // 技能初始等级（draft.attrs 提供 1-10 初始值，对应 schema 的 level）
        if (draft.attrs && typeof draft.attrs === 'object') {
          if (!s.skills) s.skills = {};
          ['meditation','exercise','insight','disguise','recovery','willpower'].forEach(k => {
            const v = Number(draft.attrs[k]);
            if (!isNaN(v) && v >= 1) {
              if (!s.skills[k]) s.skills[k] = { level: 1, exp: 0, daily_used: 0, daily_max: 30 };
              s.skills[k].level = v;
            }
          });
        }
        // 自定义因子（写入 _hidden.custom_factors 供 EJS 读取）
        if (Array.isArray(draft.custom_factors) && draft.custom_factors.length > 0) {
          if (!s._hidden) s._hidden = {};
          s._hidden.custom_factors = draft.custom_factors.map(f => ({
            name: String(f.name || ''),
            desc: String(f.desc || '')
          }));
        }
        // 启用的世界因子
        if (Array.isArray(draft.enabled_factors)) {
          if (!s._hidden) s._hidden = {};
          s._hidden.enabled_factors = draft.enabled_factors.slice();
        }
        // 启用角色名单（控制 EJS 加载哪些女性档案）
        if (Array.isArray(draft.enabled_chars)) {
          if (!s._hidden) s._hidden = {};
          s._hidden.enabled_chars = draft.enabled_chars.slice();
        }
        // 模块开关
        if (draft.modules && typeof draft.modules === 'object') {
          if (!s._hidden) s._hidden = {};
          s._hidden.modules = Object.assign({}, draft.modules);
        }
        // 标记初始化完成
        if (!s._hidden) s._hidden = {};
        s._hidden.$已初始化 = true;
        s._hidden.opening_completed = true;
        s._hidden.opening_timestamp = Date.now();
        return data;
      });
      console.log('[假阴茎卡] 开局页草稿已写入 MVU 变量');
      // 推送状态栏
      setTimeout(pushStatDataToStatusBars, 300);
      return true;
    } catch (e) {
      console.error('[假阴茎卡] applyOpeningDraft 失败:', e.message);
      return false;
    }
  }

  // 隐藏所有开局页挂载点
  function hideAllOpeningPages() {
    const docs = [document];
    try { if (hostWindow().document) docs.push(hostWindow().document); } catch (_) {}
    docs.forEach(doc => {
      const mounts = doc.querySelectorAll('[' + OPENING_FLAG_ATTR + ']');
      for (let i = 0; i < mounts.length; i++) {
        const m = mounts[i];
        m.style.display = 'none';
        m.setAttribute('data-fjb-opening-completed', '1');
        // 同时隐藏占位展开的外层 div（开局页占位展开 regex 输出的容器）
        let parent = m.parentElement;
        while (parent && parent !== doc.body) {
          if (parent.getAttribute && parent.getAttribute('data-fjb-opening')) break;
          parent = parent.parentElement;
        }
      }
    });
  }

  function registerMessageListener() {
    const handler = (event) => {
      if (!event || !event.data) return;
      const data = event.data;
      if (data.type === 'fjb-mvu-stat-request') { pushStatDataToStatusBars(); return; }
      if (data.type === 'fjb-set-theme' && data.theme) {
        // 只同步持久化，不再重新广播（否则 applyThemeToStatusBars → postMessage → 本监听器 → applyThemeToStatusBars 无限循环卡死）
        setTheme(data.theme);
      }
      if (data.type === 'fjb-cc-get-state') {
        const state = { switches: getSwitches(), theme: getTheme() };
        try { event.source.postMessage({ type: 'fjb-cc-state', state: state }, event.origin || '*'); } catch (_) {}
      }
      if (data.type === 'fjb-cc-set-switch' && data.key) setSwitch(data.key, !!data.value);
      // ★ 开局页：请求打开控制中心 ★
      if (data.type === 'fjb-open-control-center') {
        try { togglePanel(); } catch (e) { console.warn('[假阴茎卡] togglePanel 失败:', e.message); }
      }
      // ★ 开局页：发送开局确认（draft 应用 + 隐藏开局页） ★
      if (data.type === 'fjb-opening-confirm' && data.draft) {
        console.log('[假阴茎卡] 收到开局确认，开始应用 draft...');
        applyOpeningDraft(data.draft).then(ok => {
          if (ok) {
            // 应用成功后隐藏开局页
            setTimeout(hideAllOpeningPages, 200);
            // 给开局页 iframe 反馈
            try {
              event.source.postMessage({
                type: 'fjb-opening-confirm-ack',
                success: true,
                timestamp: Date.now()
              }, event.origin || '*');
            } catch (_) {}
          } else {
            try {
              event.source.postMessage({
                type: 'fjb-opening-confirm-ack',
                success: false,
                error: 'MVU 变量写入失败',
                timestamp: Date.now()
              }, event.origin || '*');
            } catch (_) {}
          }
        });
      }
    };
    window.addEventListener('message', handler);
    addDisposer(() => window.removeEventListener('message', handler));
  }

  // ========================================================================
  // 第二十二章 检查云端版本
  // ========================================================================
  async function checkRemoteVersion() {
    // 全量内嵌模式：不再从 CDN 拉取 manifest.json
    return null;
  }

  // ========================================================================
  // 第二十三章 初始化
  // ========================================================================
  async function init() {
    console.log('[假阴茎卡] 控制中心脚本开始执行 v' + VERSION + ' runtime:' + RT_VERSION);
    // 设置内嵌开局页回退 HTML
    try { window.__fjbOpeningFallbackHtml = decodeEmbeddedB64(EMBEDDED_OPENING_PAGE_B64); } catch (_) {}
    // 注：destroyPreviousRuntime() 已移至 IIFE 末尾 api 赋值前调用，
    // 否则在此处调用时 FjbControlCenter 已是新 api，previous===api 永真，旧实例不销毁
    // 立即发布 HUD 桥接（状态栏iframe需要通过 parent.__FJB_HUD_BRIDGE 获取变量数据）
    try { publishHudBridge(); console.log('[假阴茎卡] HUD桥接已发布'); } catch (e) { console.warn('[假阴茎卡] publishHudBridge 失败:', e.message); }
    // DOM 就绪
    if (document.readyState === 'loading') {
      await new Promise(r => document.addEventListener('DOMContentLoaded', r));
    }
    await new Promise(r => setTimeout(r, 300));
    // 应用主题（非致命，失败继续）
    try { applyThemeToStatusBars(getTheme()); } catch (e) { console.warn('[假阴茎卡] applyTheme 失败:', e.message); }
    // 悬浮球（非致命，失败继续）
    try { ensureBall(); } catch (e) { console.warn('[假阴茎卡] ensureBall 失败:', e.message); }
    // 老式注入（兼容保留）
    try { await injectStatusBars(); } catch (e) { console.warn('[假阴茎卡] injectStatusBars 失败:', e.message); }
    try { await injectOpeningPages(); } catch (e) { console.warn('[假阴茎卡] injectOpeningPages 失败:', e.message); }
    try { await injectOmniUI(); } catch (e) { console.warn('[假阴茎卡] injectOmniUI 失败:', e.message); }
    try { await injectBubbleCSS(); } catch (e) { console.warn('[假阴茎卡] injectBubbleCSS 失败:', e.message); }
    // 事件系统（非致命，失败继续）
    try { registerTavernEvents(); } catch (e) { console.warn('[假阴茎卡] registerTavernEvents 失败:', e.message); }
    try { registerMessageListener(); } catch (e) { console.warn('[假阴茎卡] registerMessageListener 失败:', e.message); }
    try { injectGenerationPrompts(); } catch (e) { console.warn('[假阴茎卡] injectGenerationPrompts 失败:', e.message); }
    // 首次主动推送
    setTimeout(pushStatDataToStatusBars, 1500);
    // 检查云端版本
    checkRemoteVersion().then(m => {
      if (m && m.version && m.version !== RT_VERSION) console.log('[假阴茎卡] 云端有新版本:', m.version);
    });
    // 定期检查（悬浮球 + 新挂载点 + 数据推送兜底）
    const intervalId = setInterval(() => {
      const sw = getSwitches();
      if (sw.floatball) {
        const root = hostDocument();
        if (!root.getElementById(BALL_ID)) ensureBall();
      }
      injectStatusBars();
      injectOpeningPages();
      injectOmniUI();
      pushStatDataToStatusBars();
    }, 2000);
    addDisposer(() => clearInterval(intervalId));
    console.log('[假阴茎卡] 控制中心 v' + VERSION + ' 初始化完成, runtime:', RT_VERSION, 'owner:', runtimeOwner.id);
  }

  // ========================================================================
  // 第二十四章 导出 destroy 接口（供下次实例化时销毁旧实例）
  // ========================================================================
  const api = {
    version: VERSION,
    destroy() {
      runAllDisposers();
      resetHudLoad();
      try { delete hostWindow()[BRIDGE_KEY]; } catch (_) {}
      try { delete hostWindow().FjbControlCenter; } catch (_) {}
      console.log('[假阴茎卡] 控制中心 v' + VERSION + ' 已销毁');
    },
    openHudPanel,
    closeHudPanel,
    togglePanel,
    pushStatDataToStatusBars,
    getSwitches,
    setSwitch,
    getTheme,
    setTheme,
  };
  // 销毁旧实例（必须在 FjbControlCenter 赋值前调用！
  // 原bug：此处先赋值再在init内调用destroy，导致 previous===api 永真，旧实例不销毁，
  // 旧悬浮球残留DOM，ensureBall检测到旧球跳过创建，悬浮按钮永远不出现）
  destroyPreviousRuntime();

  hostWindow().FjbControlCenter = api;

  // 启动
  init().catch(e => console.error('[假阴茎卡] 控制中心初始化失败:', e));
})();

$(async () => {
  await waitGlobalInitialized('Mvu');
  let hook = null;
  if (typeof window !== 'undefined' && window.TavernHelper) {
    hook = window.TavernHelper.on('message', function onMessage(message) {
      // 注：UpdateVariable / UpdateTable / Thinking 块的折叠美化与AI隐藏
      //     全部由 01~07 号正则脚本接管（见 正则/ 目录），
      //     此脚本仅负责正则不覆盖的杂项清理与时间戳美化。

      // 1. 清理其他隐藏块（不属于 UpdateVariable/UpdateTable/Thinking 的）
      message = message.replace(/<\|不发送\|>[\s\S]*?<\|\/不发送\|>/g, '');
      message = message.replace(/<!--\s*不发送[\s\S]*?-->/g, '');
      message = message.replace(/\[\/\/\]:\s*#\s*\(不发送\)[\s\S]*?(?=\n\n|\n---|\n$|$)/g, '');
      message = message.replace(/\*\*\[不发送\]\*\*[\s\S]*?(?=\n\n|\n---|\n$)/g, '');
      message = message.replace(/<thought>[\s\S]*?<\/thought>/g, '');
      message = message.replace(/<system>[\s\S]*?<\/system>/gi, '');

      // 2. 时间戳美化
      message = message.replace(/\*\*📅\s*(.+?)\*\*\n/g, '<div style="font-size:0.85em;color:#888;margin:4px 0;">📅 $1</div>\n');
      message = message.replace(/\*\*⏰\s*(.+?)\*\*\n/g, '<div style="font-size:0.85em;color:#888;margin:4px 0;">⏰ $1</div>\n');

      return message;
    });
  }
  $(window).on('pagehide', () => { if (hook && window.TavernHelper) window.TavernHelper.removeListener('message', hook); });
});

$(async () => {
  await waitGlobalInitialized('Mvu');

  const styleId = 'tavern-beautifier-styles';
  if (!document.getElementById(styleId)) {
    const style = document.createElement('style');
    style.id = styleId;
    style.textContent = `
      .stat-badge, .skill-badge { transition: all 0.2s ease; }
      .stat-badge:hover, .skill-badge:hover { transform: scale(1.05); filter: brightness(1.15); }
      blockquote { transition: border-color 0.3s; }
      blockquote:hover { border-left-color: #ff69b4 !important; }
    `;
    document.head.appendChild(style);
  }

  let hook = null;
  if (typeof window !== 'undefined' && window.TavernHelper) {
    hook = window.TavernHelper.on('message', function onMessage(message) {
      const badges = [
        { pattern: /\*\*精力[:：]\s*(\d+)\s*\/\s*(\d+)\*\*/g, html: '<span class="stat-badge energy-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff1493;margin:0 2px;">⚡ 精力 $1/$2</span>' },
        { pattern: /\*\*理智[:：]\s*(\d+)\s*\/\s*100\*\*/g, html: '<span class="stat-badge sanity-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff69b4;margin:0 2px;">🧠 理智 $1</span>' },
        { pattern: /\*\*疑心[:：]\s*(\d+)\s*\/\s*200\*\*/g, html: '<span class="stat-badge suspicion-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff1493;margin:0 2px;">🔍 疑心 $1/200</span>' },
        { pattern: /\*\*沉沦[:：]\s*(\d+)\s*\/\s*200\*\*/g, html: '<span class="stat-badge corruption-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff1493;margin:0 2px;">🌑 沉沦 $1/200</span>' },
        { pattern: /\*\*阶段[:：]\s*(\d+)\s*\/\s*5\*\*/g, html: '<span class="stat-badge stage-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff69b4;margin:0 2px;">📊 阶段 $1/5</span>' },
        { pattern: /\*\*学业[:：]\s*(\d+)\s*\/\s*5\*\*/g, html: '<span class="stat-badge academic-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff85a2;margin:0 2px;">📚 学业 $1/5</span>' },
        { pattern: /\*\*体力[:：]\s*(\d+)\s*\/\s*(\d+)\*\*/g, html: '<span class="stat-badge health-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff69b4;margin:0 2px;">💪 体力 $1/$2</span>' },
      ];
      for (const b of badges) message = message.replace(b.pattern, b.html);
      message = message.replace(/\*\*(冥想|锻炼|洞察|伪装|恢复|意志)[:：]\s*Lv\.(\d+)\s*\((\d+)\/100\)\*\*/g,
        '<span class="skill-badge" style="display:inline-block;background:rgba(255,182,193,0.2);backdrop-filter:blur(6px);border:1px solid rgba(255,105,180,0.4);border-radius:10px;padding:1px 8px;font-size:0.85em;color:#ff1493;margin:0 2px;">🏅 $1 Lv.$2 ($3/100)</span>');
      message = message.replace(/\|([█▌▎▍▋▊▉]+)(\s*)([█▌▎▍▋▊▉]*)\|\s*(\d+)%/g,
        '<div style="display:inline-block;width:120px;height:14px;background:rgba(255,192,203,0.2);border-radius:7px;overflow:hidden;vertical-align:middle;position:relative;">' +
        '<div style="width:$4%;height:100%;background:linear-gradient(90deg,#ffb6c1,#ff1493);border-radius:7px;transition:width 0.3s;"></div>' +
        '</div> <span style="font-size:0.8em;color:#ff69b4;">$4%</span>');
      message = message.replace(/^>\s*(.+)$/gm, '<blockquote style="border-left:3px solid #ff69b4;margin:8px 0;padding:4px 12px;color:#8b3a52;background:rgba(255,182,193,0.08);border-radius:0 8px 8px 0;">$1</blockquote>');
      message = message.replace(/^---\s*$/gm, '<hr style="border:none;border-top:1px solid rgba(255,105,180,0.3);margin:12px 0;">');
      message = message.replace(/^___\s*$/gm, '<hr style="border:none;border-top:1px dashed rgba(255,105,180,0.4);margin:12px 0;">');
      message = message.replace(/^(⚠|❗|🔴|🟡)\s*(.+)$/gm,
        '<div style="background:rgba(255,105,180,0.1);border-left:3px solid #ff1493;padding:6px 12px;margin:8px 0;color:#ff1493;font-size:0.9em;border-radius:0 8px 8px 0;">$1 $2</div>');
      if (message.includes('[状态栏]') || message.includes('[StatusBar]')) {
        message = message.replace(/\[状态栏\]/g, '');
        message = message.replace(/\[StatusBar\]/g, '');
      }
      return message;
    });
  }
  $(window).on('pagehide', () => { if (hook && window.TavernHelper) window.TavernHelper.removeListener('message', hook); });
});

const FORBIDDEN_KNOWLEDGE = [
  /假阴茎|仿真阴茎|飞机杯.*反|反向.*飞机杯|阴茎.*复制|阴茎.*投影/i,
  /具现度|阶段.*[1-5]|manifestation|stage.*[1-5]/i,
  /林婉清|苏晴|陈老师|张雨萱|林小艾|唐小糖|秦雨|周思琪|学姐|班花|校花|她.*在用|她.*用.*了/i,
  /内射|外射|边缘控制|边缘.*控制|不射|延时.*射|控制.*射精/i,
  /透视|读心|预知|瞬移|飞行|超自然|魔法|异能|修仙|灵力|念力/i
];

const FORBIDDEN_ACTIONS_LOW_SUSPICION = [
  /搜查|翻包|偷看|跟踪|监视|潜入|破门|强行/i
];

const FORBIDDEN_ACTIONS_MID_SUSPICION = [
  /对质|对峙|报警|找老师|告发|当面质问/i
];

const ABILITY_VIOLATION = [
  /我用.*能力|我发动.*|我觉醒.*|我开启.*眼|我有.*力量/i
];

function interceptPlayerInput(input, mvu) {
  const suspicion = (mvu && mvu.stat_data && mvu.stat_data.状态 && mvu.stat_data.状态.怀疑值) || 0;
  const stage = (mvu && mvu.stat_data && mvu.stat_data.使用阶段 && mvu.stat_data.使用阶段.当前阶段) || 1;

  for (const pattern of FORBIDDEN_KNOWLEDGE) {
    if (pattern.test(input)) {
      return { blocked: true, rewrite: rewriteToUserReality(input, mvu), reason: 'knowledge_violation' };
    }
  }

  if (suspicion < 50) {
    for (const pattern of FORBIDDEN_ACTIONS_LOW_SUSPICION) {
      if (pattern.test(input)) {
        return { blocked: true, rewrite: '虽然觉得最近怪怪的，但是<user>找不到任何理由去怀疑身边的人，只能继续硬撑着上课。', reason: 'insufficient_suspicion' };
      }
    }
  }

  if (suspicion < 90) {
    for (const pattern of FORBIDDEN_ACTIONS_MID_SUSPICION) {
      if (pattern.test(input)) {
        return { blocked: true, rewrite: '怀疑归怀疑，但没有证据<user>不敢轻举妄动，免得闹笑话。', reason: 'insufficient_evidence' };
      }
    }
  }

  if (suspicion < 130) {
    if (/强行搜身|破门|直接报警抓人/i.test(input)) {
      return { blocked: true, rewrite: '冲动是魔鬼，<user>深吸一口气，决定再找找确凿证据。', reason: 'rash_action' };
    }
  }

  for (const pattern of ABILITY_VIOLATION) {
    if (pattern.test(input)) {
      return { blocked: true, rewrite: '<user>只是个普通高中生，唯一的"超能力"大概是熬夜不猝死。', reason: 'ability_violation' };
    }
  }

  return { blocked: false, rewrite: input };
}

function rewriteToUserReality(input, mvu) {
  const rewrites = {
    '假阴茎': '那个……奇怪的感觉',
    '林婉清': '那个女生',
    '苏晴': '那个学姐',
    '陈老师': '那位老师',
    '张雨萱': '那个文艺委员',
    '林小艾': '那个短发女生',
    '唐小糖': '那个染头发的',
    '秦雨': '同桌',
    '周思琪': '那个图书委员',
    '在用': '让我感到疲惫',
    '内射': '那种被掏空的感觉',
    '搜查': '找借口靠近',
    '质问': '欲言又止',
    '透视': '瞪大眼睛看',
    '读心': '盯着对方脸看',
  };
  let result = input;
  for (const [k, v] of Object.entries(rewrites)) {
    result = result.replace(new RegExp(k, 'gi'), v);
  }
  return result || '<user>想了想，但什么也做不了，只能继续趴在桌上发呆。';
}

$(async () => {
  await waitGlobalInitialized('Mvu');
  eventOn('message_sent', async function onUserMessage() {
    const ctx = SillyTavern.getContext();
    const lastMsg = ctx.chat[ctx.chat.length - 1];
    if (!lastMsg || lastMsg.is_system || lastMsg.role !== 'user') return;
    const mvuData = await Mvu.getMvuData({ type: 'message', message_id: lastMsg.message_id });
    const result = interceptPlayerInput(lastMsg.mes, mvuData || {});
    if (result.blocked) {
      lastMsg.mes = result.rewrite;
      await Mvu.replaceMvuData({ ...mvuData?.stat_data }, { type: 'message', message_id: lastMsg.message_id });
    }
  });
});

