@@generate_before
<%_
// ===== LCG 确定性骰子系统 =====
// 统一为 NR LCG 参数 + 嵌套乘法种子 + EJS 预判定输出
// 参考：同级生2 LCG骰子引擎、环世界 DDL确定性骰子引擎
// 核心改进：从"AI心算"改为"EJS预roll输出结果"，确保确定性可执行
//
// ===== 确定性算法说明（DDL类确定性判定）=====
// 本系统采用 NR LCG（Numerical Recipes Linear Congruential Generator）算法
// 参数：a=1664525, c=1013904223, m=2^32
// 种子公式：((((day×7 + hour×13)×7919 + id)×11 + stage)×17 + extra)×31
// 判定制式：D100（百分比制，0-100），比传统D20（1-20）精度高5倍
//   - D20制：每档5%精度，临界值跳变明显
//   - D100制：每档1%精度，概率过渡平滑，更适配本项目多技能联动判定
// 确定性保证：相同(day,hour,id,stage,extra) → 相同判定结果 → 可复现
// 与同级生2 DDL一致性：同为NR LCG + 嵌套乘法种子 + D100制，确保确定性判定
// 属性技能联动：判定阈值由 stat_data.技能.*.等级 和 stat_data.女性角色.*.能力 动态计算
//   - 冥想/意志/洞察/伪装/锻炼/恢复 6项技能等级直接影响对应判定阈值
//   - 持有者学业压力/考试倒计时等环境因素修正概率
//   - 难度系数（普通/困难/地狱）修正基础概率

// ===== 读取全局状态（带守卫，跨文件共享变量）=====
if (typeof day === 'undefined') var day = Number(getvar('stat_data.时间.天数', {scope:'local', defaults:1})) || 1;
if (typeof hour === 'undefined') var hour = Number(getvar('stat_data.时间.小时', {scope:'local', defaults:8})) || 8;
if (typeof stage === 'undefined') var stage = Number(getvar('stat_data.使用阶段.当前阶段', {scope:'local', defaults:1})) || 1;
if (typeof totalUses === 'undefined') var totalUses = Number(getvar('stat_data.使用阶段.总使用次数', {scope:'local', defaults:0})) || 0;
if (typeof todayUses === 'undefined') var todayUses = Number(getvar('stat_data.使用阶段.今日使用', {scope:'local', defaults:0})) || 0;
if (typeof suspicion === 'undefined') var suspicion = Number(getvar('stat_data.状态.怀疑值', {scope:'local', defaults:0})) || 0;
if (typeof difficulty === 'undefined') var difficulty = getvar('stat_data.状态.难度', {scope:'local', defaults:'困难'}) || '困难';
if (typeof holderId === 'undefined') var holderId = getvar('stat_data.隐藏层.持有者ID', {scope:'local', defaults:'林婉清'}) || '林婉清';
if (typeof activeUsersCount === 'undefined') var activeUsersCount = Number(getvar('stat_data.隐藏层.活跃使用人数', {scope:'local', defaults:0})) || 0;
if (typeof diffIdx === 'undefined') var diffIdx = difficulty === '普通' ? 0 : difficulty === '地狱' ? 2 : 1;

// 持有者ID 存的是中文姓名，需遍历 女性角色 反查 UID
if (typeof holderUid === 'undefined') var holderUid = '';
if (holderUid === '') {
  try {
    var _allFem = getvar('stat_data.女性角色', {scope:'local', defaults:{}}) || {};
    for (var _uid in _allFem) {
      if (_allFem.hasOwnProperty(_uid) && _allFem[_uid] && _allFem[_uid].基础 && _allFem[_uid].基础.姓名 === holderId) {
        holderUid = _uid;
        break;
      }
    }
  } catch(e) {}
}

// ===== LCG 引擎函数（本条目本地定义，因 getwi 隔离作用域无法跨条目共享）=====
// 参数：a=1664525, c=1013904223, m=2^32 (Numerical Recipes LCG)
// 种子公式：((((day*7 + hour*13)*7919 + id)*11 + stage)*17 + extra)*31
// 注：全局规则总表.txt 中也有相同定义（带守卫），但 getwi 调用隔离作用域，本条目必须本地定义
if (typeof LCG_A === 'undefined') var LCG_A = 1664525;
if (typeof LCG_C === 'undefined') var LCG_C = 1013904223;
if (typeof LCG_M === 'undefined') var LCG_M = 4294967296;
if (typeof _lcgNext === 'undefined') var _lcgNext = function(seed) {
  return ((seed >>> 0) * LCG_A + LCG_C) >>> 0;
};
if (typeof _lcgDouble === 'undefined') var _lcgDouble = function(seed) {
  return _lcgNext(seed) / LCG_M;
};
if (typeof _makeSeed === 'undefined') var _makeSeed = function(id, extra, day, hour, stage) {
  var d = (typeof day !== 'undefined') ? day : Number(getvar('stat_data.时间.天数', {scope:'local', defaults:1})) || 1;
  var h = (typeof hour !== 'undefined') ? hour : Number(getvar('stat_data.时间.小时', {scope:'local', defaults:8})) || 8;
  var s = (typeof stage !== 'undefined') ? stage : Number(getvar('stat_data.使用阶段.当前阶段', {scope:'local', defaults:1})) || 1;
  var e = extra || 0;
  return (((((d * 7 + h * 13) * 7919 + id) * 11 + s) * 17 + e) * 31) >>> 0;
};
// 5档百分比判定（修复版，tier无重复赋值，含"极难成功"/"困难成功"）
if (typeof _percentRoll === 'undefined') var _percentRoll = function(probability, seed) {
  var val = _lcgDouble(seed);
  var success = val < (probability / 100);
  var tier;
  if (val < 0.05) tier = '大成功';
  else if (val < probability / 500) tier = '极难成功';
  else if (val < probability / 200) tier = '困难成功';
  else if (success) tier = '成功';
  else if (val > 0.95) tier = '大失败';
  else tier = '失败';
  return { success: success, value: val, tier: tier, dice: Math.round(val * 100) };
};

// CoC 风格 5 档判定（参考环世界 DDL）：threshold 为 0-100 属性值
// 本函数仅本条目使用，加守卫避免重复声明
if (typeof _check === 'undefined') var _check = function(threshold, seed, difficultyLabel) {
  var val = _lcgDouble(seed) * 100;
  var t = Number(threshold) || 0;
  var diff = difficultyLabel || '普通';
  var effT = diff === '困难' ? t / 2 : diff === '极难' ? t / 5 : t;
  var result;
  if (val <= 5) result = '大成功';
  else if (val <= effT / 5) result = '极难成功';
  else if (val <= effT / 2) result = '困难成功';
  else if (val <= effT) result = '普通成功';
  else if (val >= 96) result = '大失败';
  else result = '失败';
  return { result: result, roll: Math.round(val), threshold: effT, success: result.indexOf('成功') >= 0 };
};

// ===== 预判定：今日关键事件 =====

// 1. 持有者今日使用判定
