  holderProb = holderProb + 5;
}
holderProb = Math.max(5, Math.min(95, holderProb)); // 钳制到 5%-95%
var holderUseRoll = _percentRoll(holderProb, holderSeed);

// 2. 传播判定（如果持有者使用且 activeUsersCount < 25）
