  endingRoll = { value: endingVal, dice: Math.round(endingVal * 100) };
}

// ===== P2-18: RPG 系统判定（LCG骰子落地到RPG）=====
// 6. 制造配方成功判定
var craftSeed = _makeSeed(6, 600);
var craftLv = Number(getvar('stat_data.技能.洞察.等级', {scope:'local', defaults:1})) || 1;
var craftThreshold = 30 + craftLv * 2; // 制造成功率：基础30% + 洞察等级×2%
if (craftThreshold > 90) craftThreshold = 90;
