// 7. 探索遭遇判定（雷达.信号 检测异常信号）
var exploreSeed = _makeSeed(7, 700);
var radarSys = getvar('stat_data.雷达.信号', {scope:'local', defaults:[]}) || [];
var exploreThreshold = 25 + stage * 5 + (radarSys.length > 0 ? 10 : 0); // 探索遭遇率：基础25% + 阶段×5% + 雷达+10%
if (exploreThreshold > 85) exploreThreshold = 85;
var exploreRoll = _percentRoll(exploreThreshold, exploreSeed);

// 8. 资产品质判定（商店商品 刷新品质）
var qualitySeed = _makeSeed(8, 800);
var qualityVal = _lcgDouble(qualitySeed);
var shopQualityTier;
if (qualityVal < 0.50) shopQualityTier = 'common';      // 50% 普通
else if (qualityVal < 0.80) shopQualityTier = 'rare';    // 30% 稀有
else if (qualityVal < 0.95) shopQualityTier = 'epic';    // 15% 史诗
else shopQualityTier = 'legendary';                       // 5% 传说

// 9. 载具机动判定（避险成功率）
var vehicleSeed = _makeSeed(9, 900);
var vehicles = getvar('stat_data.载具', {scope:'local', defaults:[]}) || [];
var vehicleThreshold = vehicles.length > 0 ? 60 : 20; // 有载具60%避险，无载具20%
var vehicleRoll = _percentRoll(vehicleThreshold, vehicleSeed);

// 10. 居所安全事件判定
var residenceSeed = _makeSeed(10, 1000);
var residences = getvar('stat_data.居所', {scope:'local', defaults:[]}) || [];
var residenceSafety = residences.length > 0 ? Number(residences[0].安全等级 || 50) : 50;
var residenceEventThreshold = 100 - residenceSafety; // 安全度越高事件越少
var residenceRoll = _percentRoll(residenceEventThreshold, residenceSeed);

// ===== P2-19: 玩家主动行为预判定（每轮为常见玩家行为预生成骰子结果）=====
// 所有玩家主动行为必须走LCG判定，AI读取下方结果决定成败
if (typeof meditationLv === 'undefined') var meditationLv = Number(getvar('stat_data.技能.冥想.等级', {scope:'local', defaults:1})) || 1;
if (typeof exerciseLv === 'undefined') var exerciseLv = Number(getvar('stat_data.技能.锻炼.等级', {scope:'local', defaults:1})) || 1;
var willpowerLv2 = Number(getvar('stat_data.技能.意志.等级', {scope:'local', defaults:1})) || 1;

// 11. 冥想感知判定（感知使用者）
var medSeed = _makeSeed(11, 1100);
var medThreshold = meditationLv * 2; // 冥想等级×2%
