// 12. 洞察观察判定（发现异常线索）
var obsSeed = _makeSeed(12, 1200);
var obsThreshold = 20 + insightLv * 3; // 基础20% + 洞察×3%
if (obsThreshold > 85) obsThreshold = 85;
