// 16. 社交互动判定（好感度提升/信息获取）
var socialSeed = _makeSeed(16, 1600);
var socialThreshold = 35 + insightLv * 2; // 基础35% + 洞察×2%
if (socialThreshold > 85) socialThreshold = 85;
