// 17. 调查行为判定（搜查物品/跟踪）
var invSeed = _makeSeed(17, 1700);
var invThreshold = 15 + insightLv * 3 + (suspicion >= 60 ? 15 : 0); // 基础15% + 洞察×3% + 疑心≥60加成15%
if (invThreshold > 80) invThreshold = 80;
var invRoll = _percentRoll(invThreshold, invSeed);

// ===== 辅助：当前时段（9时段制，与时间轴系统一致）=====
var timeSlot;
if (hour >= 5 && hour < 7) timeSlot = '早晨';
else if (hour >= 7 && hour < 8) timeSlot = '晨读';
else if (hour >= 8 && hour < 12) timeSlot = '上午';
else if (hour >= 12 && hour < 14) timeSlot = '中午';
