var energy = Number(getvar('stat_data.状态.精力', {scope:'local', defaults:80})) || 80;
var sanity = Number(getvar('stat_data.状态.理智', {scope:'local', defaults:80})) || 80;
var corruption = Number(getvar('stat_data.状态.堕落值', {scope:'local', defaults:0})) || 0;
var pc = getvar('stat_data.隐藏层.传播链', {scope:'local', defaults:[]}) || []; var chain_count = Array.isArray(pc) ? pc.length : 0;
var exam = Number(getvar('stat_data.学业.考试倒计时', {scope:'local', defaults:103})) || 103;
var score = Number(getvar('stat_data.学业.分数', {scope:'local', defaults:75})) || 75;
var academic = Number(getvar('stat_data.学业.阶段', {scope:'local', defaults:3})) || 3;
var day = Number(getvar('stat_data.时间.天数', {scope:'local', defaults:1})) || 1;
var hour = Number(getvar('stat_data.时间.小时', {scope:'local', defaults:8})) || 8;

// LCG 函数
function lcg_next(s) { var a=1664525,c=1013904223,m=4294967296; return ((s*a+c)>>>0); }

// 计算女性总战力
var femaleCombatPower = 0;
var femaleCount = 0;
var uidOrder = getvar('stat_data.女性角色.UID顺序', {scope:'local', defaults:[]});
var idMul = Number(getvar('stat_data.配置.LCG常数.ID乘数', {scope:'local', defaults:7919})) || 7919;

if (Array.isArray(uidOrder)) {
  uidOrder.forEach(function(uid) {
    var abilities = getvar('stat_data.女性角色.' + uid + '.能力', {scope:'local', defaults:null});
    if (abilities && abilities.技能等级 !== undefined) {
      var avg = (Number(abilities.技能等级) + Number(abilities.隐蔽) + Number(abilities.持久) + Number(abilities.控制) + Number(abilities.诱惑) * 0.5 + Number(abilities.欲望) * 0.5) / 5;
      femaleCombatPower += avg;
      femaleCount++;
    }
  });
}

if (femaleCount > 0) {
  femaleCombatPower = femaleCombatPower / femaleCount;        // 平均能力
  femaleCombatPower = femaleCombatPower * (1 + femaleCount * 0.05);  // 人数加权
  femaleCombatPower = femaleCombatPower * (1 + corruption / 200);    // 沉沦放大器
}

// 玩家战力
var playerCombatPower = (
  meditation * 0.30 +    // 定力（意识）
  willpower * 0.25 +     // 意志（抗性）
  energy * 0.20 +        // 精力（生命力）
  sanity * 0.15 +        // 理智（清醒度）
  insight * 0.10          // 洞察（感知）
) * (1 + (100 - corruption) / 200);  // 低沉沦增益

if (suspicion >= 150 || total_uses >= 100) {
  // 觉醒进度计算（100级公式）
  var progress = 0;
  progress += Math.min(40, suspicion * 0.2);       // 疑心度贡献
  progress += Math.min(30, meditation * 0.3);       // 定力贡献
  progress += Math.min(20, exercise * 0.2);          // 体质贡献
  progress += Math.min(15, insight * 0.15);           // 洞察贡献
  progress -= Math.min(30, corruption * 0.3);        // 沉沦度扣减
  progress = Math.max(0, Math.min(100, progress));

  // 能力对抗 LCG 骰子
  var powerRatio = playerCombatPower > 0 ? Math.min(5.0, Math.max(0.2, femaleCombatPower / playerCombatPower)) : 1.0;
  var combatSeed = (((((day * 7 + hour * 13) * 7919 + Math.floor(femaleCombatPower)) * 11 + stage) * 17 + Math.floor(playerCombatPower)) * 31) >>> 0;
  var combatRoll = lcg_next(combatSeed) % 10000 / 10000;

  // 对抗结果：0~1 越小对玩家越有利
  var combatOutcome = combatRoll < powerRatio * 0.35 ? 'female_dominant' : (combatRoll > 1 - powerRatio * 0.20 ? 'player_dominant' : 'balanced');

  setvar('stat_data.隐藏层.觉醒进度', progress);
  setvar('stat_data.隐藏层.女性战斗力', Math.round(femaleCombatPower * 100) / 100);
  setvar('stat_data.隐藏层.玩家战斗力', Math.round(playerCombatPower * 100) / 100);
  setvar('stat_data.隐藏层.对抗结果', combatOutcome);

  // 终局分支判定（100级/5档条件 + 能力对抗修正·统一中文键名）
  if (combatOutcome === 'female_dominant' && corruption >= 60) {
    // 女性掌控结局
    setvar('stat_data.结局.黑市掌控', true, {scope:'local'});
  } else if (combatOutcome === 'player_dominant' && progress >= 80 && meditation >= 61 && energy > 30) {
    // 真相大白（最佳结局）
    setvar('stat_data.结局.真相揭示', true, {scope:'local'});
  } else if (progress >= 80 && meditation >= 61 && energy > 30) {
    setvar('stat_data.结局.真相揭示', true, {scope:'local'});
  } else if (progress >= 60 && energy > 20) {
    setvar('stat_data.结局.平庸', true, {scope:'local'});
  } else if (progress >= 40 && energy > 0) {
    setvar('stat_data.结局.坠落', true, {scope:'local'});
  } else {
    setvar('stat_data.结局.崩坏', true, {scope:'local'});
  }
}
%>

# 顶层根: 基础信息 / 时间 / 状态 / 技能 / 使用阶段 / 学业 / 隐藏层 / 骰子 / 症状 / 环境 / 女性角色 / 任务 / 商店商品 / 物品栏 / 仓库 / 已放置物品 / 制造配方 / 载具 / 居所 / 检定建议 / 雷达 / 规则变化 / 关系图谱 / 事件 / 结局 / 陌生模板 / 课程表 / 配置 / UID计数器
# 操作仅支持: replace / add / remove（RFC 6902）
# 字段名以 _ 或 $ 开头的为只读，禁止更新

基础信息:
  ${姓名|性别|学校|班级}:
    check:
      - 仅在开场、入学、转学、升学、毕业或玩家明确身份变化时 replace。
      - 姓名 初始为 {{user}}，玩家自报后 replace。
  年龄:
    type: number

时间:
  ${天数|小时|分钟|学期天数|距高考天数}:
    type: number
    check:
      - 每轮时间推进 replace 为新值。
      - 分钟 范围 0~59，进位时 replace 小时 为 +1 后的值。
      - 小时 超过 23 时，replace 天数为 +1 后的值，小时归零。
      - 学期天数 >= 120 时 replace 学期 为下一阶段；距高考天数 = 0 时 replace 学期 为"高考后"。
      - 距高考天数 每过一天 replace 为 -1 后的值，至 0 后保持 0。
  ${星期|日期|考试期|学期}:
    check:
      - 跨日或跨学期时 replace 对应值。
      - 学期 枚举：高三上/高三下/高考后；初始为"高三下"。

状态:
  ${精力|精力上限|理智|健康|压力|金钱|怀疑值|堕落值|体力|体力上限}:
    type: number
    range:
      精力: 0~精力上限
      精力上限: 30~100
      理智: 0~100
      健康: 0~100
      压力: 0~100
      怀疑值: 0~200
      堕落值: 0~200
      体力: 0~体力上限
      体力上限: 30~100
    check:
      - 数值变化 replace 为计算后的新值。
      - 怀疑值/堕落值 上限 200。
      - 精力上限/体力上限 为难度锁定值，仅在难度切换时由变量 AI 按下表 replace，此后不可再修改。
      - ★难度初始值铁律表（必须严格按此表 replace，禁止 AI 自行编造数值）：
        · 普通：精力上限=100, 体力上限=100, 精力=100, 体力=100, 理智=100, 健康=90, 压力=5, 金钱=800
        · 困难：精力上限=80, 体力上限=80, 精力=80, 体力=80, 理智=80, 健康=75, 压力=10, 金钱=500
        · 地狱：精力上限=60, 体力上限=60, 精力=60, 体力=60, 理智=60, 健康=60, 压力=20, 金钱=300
      - 禁止设置超出上表的数值（如地狱难度下精力上限=160/体力上限=200 属于严重违规）。
  难度:
    type: string
    check:
      - 枚举：普通/困难/地狱；初始为"困难"。
      - 仅在 隐藏层.难度已锁定 === false 时允许 replace；锁定后禁止修改。
      - 难度切换由变量 AI 根据玩家开局选择自动执行，必须一次性输出以下全部 patch：
        1. replace /状态/难度 = 选择的难度
        2. replace /隐藏层/难度已锁定 = true
        3. replace /状态/精力上限 = 对应难度的精力上限（普通100/困难80/地狱60）
        4. replace /状态/体力上限 = 对应难度的体力上限（普通100/困难80/地狱60）
        5. replace /状态/精力 = 对应难度的初始精力
        6. replace /状态/体力 = 对应难度的初始体力
        7. replace /状态/理智 = 对应难度的初始理智
        8. replace /状态/健康 = 对应难度的初始健康
        9. replace /状态/压力 = 对应难度的初始压力
        10. replace /状态/金钱 = 对应难度的初始金钱
      - 以上 10 个 patch 必须在同一轮 VARIABLE_UPDATE 中一次性输出，缺一不可。
  今日生活费已领取:
    type: boolean
    check:
      - 每日由触发器重置为 false；领取后 replace 为 true。
  每日购买:
    type: object
    check:
      - 子字段当日累计，每日重置；购买时 replace 对应子字段为新值。

技能:
  ${冥想|锻炼|洞察|伪装|恢复|意志}:
    type: |-
      {
        等级: number;
        经验: number;
        今日已用: number;
        今日上限: number;
      }
    range:
      等级: 1~100
      经验: 0~9900
      今日已用: 0~今日上限
      今日上限: 1~100
    check:
      - 经验增长 replace 为新值；等级提升 replace 为新值（经验每 100 提一级）。
      - 今日已用 每次使用 replace 为 +1 后的值；今日已用 >= 今日上限 时当日不再增长经验。
      - 今日已用 跨日由触发器重置。
      - 今日上限 由配置决定，不同技能不同；AI 不可直接 replace。

使用阶段:
  当前阶段:
    type: number
    range: 1~5
    check:
      - 升级条件（多维度，非纯经验阈值）：
        阶段1→2: 持有者信息.是否使用过=true
        阶段2→3: 传播人数>=3 + 持有者执念>=30
        阶段3→4: 传播人数>=6 + 至少1人综合阶段=C_沉沦期
        阶段4→5: 传播人数>=10 + 至少1人综合阶段=D_疯狂期 + 怀疑值>=60
      - 升级时 replace 为新值，replace 阶段进度 为 0。
  ${总使用次数|今日使用|今日上限|最后使用日|最后使用时|阶段进度|经验|今日经验|今日经验上限}:
    type: number
    check:
      - 总使用次数/今日使用/经验 replace 为累加后的新值；今日使用/今日经验 跨日由触发器重置。
      - 最后使用日/最后使用时 replace 为当前 天数/小时。
      - 今日上限/今日经验上限 由配置决定，AI 不可直接 replace。

学业:
  ${分数|今日学习次数|考试倒计时|老师关注度}:
    type: number
    range:
      分数: 0~100
      考试倒计时: 0~35
    check:
      - 分数 变化 replace 为新值；学习 +2/次，被使用 -3/次，压力 -1~3，老师关注 +1~3。
      - 今日学习次数 当日累计，跨日由触发器重置。
      - 考试倒计时 每过一天 replace 为 -1 后的值；至 0 时考试触发，次日由触发器重置为下一周期（周考=7，月考=30，季考=90）。
      - 老师关注度 变化 replace 为新值。
  阶段:
    type: number
    check:
      - 由脚本根据 分数 自动计算（90→5, 75→4, 60→3, 40→2, 其余→1），AI 禁止手写。
  ${当前课程|当前老师|下节课程|下节老师}:
    type: string
    check:
      - 每轮根据课程表 replace 为当前/下节课程名和老师名。
      - 课间或放学时 replace 为空字符串。

隐藏层:
  难度已锁定:
    type: boolean
    check:
      - 初始 false；玩家在开局选择难度后 replace 为 true，此后不可改回 false。
      - true 时禁止 replace /状态/难度。
      - 难度锁定铁律：一旦设为 true，任何情况下都不得改回 false。
  ${超自然妄想计数|违法计数|连续拒绝}:
    type: number
    check:
      - 超自然妄想计数：剧情 AI 驳回超自然口胡时 replace 为 +1 后的值；累计 ≥3 触发 坏结局.精神异常。
      - 违法计数：剧情 AI 执行违法后果时，replace 为 +对应增量后的值；累计 ≥3 触发 坏结局.法律制裁。
      - 连续拒绝：每次 /reject 时 replace 为 +1 后的值；正常回复时 replace 归 0。
  坏结局已触发:
    type: boolean
    check:
      - 触发条件：超自然妄想计数≥3 → '精神异常'；违法计数≥3 → '法律制裁'；理智≤0 或 堕落值≥200 → '崩坏'；怀疑值≥200 且 传播≥15 → '黑市掌控'；怀疑值≥150 且 选择摧毁 且 当前阶段≥4 → '同归于尽'；第120天且未达成其他结局 → '未解之谜'。
      - 触发后 replace 为 true，不再接受任何继续剧情的指令。
  坏结局类型:
    check:
      - 触发时 replace 为对应类型字符串。
  坏结局描述:
    type: string
    check:
      - 触发坏结局时 replace 为描述文本。
  近期事件:
    type: |-
      {
        [事件id: string]: {
          事件id: string;
          时间: string;
          地点: string;
          类型: string;
          参与者: string[];
          摘要: string;
          影响: string;
          后续钩子: string;
          重要度: string;
          更新时间: string;
        }
      }
    check:
      - 新事件 add /隐藏层/近期事件/<事件id> 完整事件对象。
      - 同事件推进 replace /隐藏层/近期事件/<事件id> 对应子字段。
      - 结果失效/合并/过期 remove 对应事件。
      - 事件id 沿用当前存档既有编号体系；新增事件用当前最大编号 +1，补足三位。
      - 参与者 字段是字符串数组，replace 整个数组，不单独 add/remove 元素。
      - 近期事件数量超过 20 条时执行压缩，压缩后总数不超过 10 条。
      - 压缩保留集：最近 4 条 + 重要度最高 2 条 + 涉及关键角色 2 条 + 仍有后续钩子 1 条 = 9 条。
      - 未进入保留集的旧事件合并为 1 条 阶段归档 事件。
      - 生成归档后必须 remove 所有已被归档且未进入保留集的旧事件。
  # ── 以下字段为脚本运行时暂存，AI 只读，禁止 replace/add/remove ──
  ${真相|持有者ID|持有者获取方式|持有者获取日|持有者包裹状态|持有者首次使用日}:
    check:
      - 脚本运行时暂存，AI 只读。
      - 持有者ID/持有者获取方式/持有者获取日 在持有者变更时由脚本 replace。
  ${持有者历史|传播链|确认使用者|最后持有者|最后榨取量|射精被阻止|清醒射精}:
    check:
      - 脚本运行时暂存，AI 只读。
  ${使用模式|使用节奏|当前场景|活跃使用人数|上一日|觉醒进度}:
    check:
      - 脚本运行时暂存，AI 只读。
  ${过热保护|间隔保护|持有者过热保护|阶段已晋升|女性战斗力|玩家战斗力|对抗结果}:
    check:
      - 脚本运行时暂存，AI 只读。
  发现进度:
    type: object
    check:
      - 脚本运行时暂存，AI 只读；子字段（四阶段成功/五阶段成功/总调查次数/持有者暴露事件/孩子相似事件）由脚本自动更新。

症状:
  ${疲劳描述|敏感描述|外观描述|理智描述}:
    check:
      - 由 AI 根据当前状态描写，每次使用后 replace 对应字段。
      - 疲劳描述依据 精力/精力上限 比例；敏感描述依据 使用阶段.当前阶段；外观描述依据 精力+理智 综合；理智描述依据 理智 值。

骰子:
  type: |-
    {
      持有者使用: number;
      传播基值: number;
      怀疑抵抗: number;
      女性使用: record<string, number>;
      阶段晋升: record<string, number>;
    }
  check:
    - LCG 骰子结果暂存区，由脚本自动写入，AI 只读，禁止 replace/add/remove。
    - 持有者使用/传播基值/怀疑抵抗 为全局骰子基值（0~100）。
    - 女性使用 为每女性独立骰子值，key 为角色 UID。
    - 阶段晋升 为阶段晋升骰子结果，key 为角色 UID。

环境:
  ${天气|温度|位置|湿度|季节|天气描述|环境描述}:
    check:
      - 天气/温度/湿度/季节 跨日或天气变化时 replace。
      - 位置 随玩家移动 replace。
      - 天气描述/环境描述 每轮根据当前场景 replace。
      - 季节 依据 天数 推进（每90天换季）。
  ${气温|当前位置|风|降水|空气质量|光线|噪音|人群密度|交通|治安|区域|描述}:
    check:
      - 由 AI 根据场景 replace 为对应值。
      - 气温 为温度的补充描述；当前位置 为位置的别名字段。
  活动:
    type: record<string, { 编号: string; 标题: string; 名称: string; 截止: string; 时间: string; 描述: string; 简述: string; }>
    check:
      - 新增活动 add /环境/活动/<编号> 完整对象。
      - 活动结束 remove 对应条目。
  新闻:
    type: record<string, { 编号: string; 标题: string; 头条: string; 热度: number; 重要性: number; 内容: string; 摘要: string; 来源: string; 时间: string; 位置: string; 状态: string; }>
    check:
      - 新增新闻 add /环境/新闻/<编号> 完整对象。
      - 新闻过期 remove 对应条目。

女性角色:
  UID顺序:
    type: string[]
    check:
      - 记录角色出场顺序，仅由脚本维护，AI 只读。
  type: |-
    {
      [真名: string]: {
        基础: object;
        身体: object;
        人格: object;
        NSFW: object;
        能力: object;
        成长: object;
        与玩家关系: object;
        使用习惯: object;
        关系网: object;
        传播: object;
        多维状态: object;
        当前状态: object;
        叙事: object;
        生育: object;
        持有者信息: object;
      }
    }
  check:
    - 路径用真名（如 /女性角色/林婉清/），禁止用 female_user_xxx。
    - stat_data 中已有的女性角色，逐字段 replace 更新变化部分，禁止 add 覆盖整个角色对象。
