// 参数：a=1664525, c=1013904223, m=2^32 (Numerical Recipes)
function _lcg(seed) {
  var a = 1664525;
  var c = 1013904223;
  var m = 4294967296; // 2^32
  var state = seed >>> 0;
  state = (state * a + c) >>> 0;
  return state;
}
function _roll(seed) {
  return _lcg(seed) / 4294967296;
}
function _check(seed, threshold) {
  // threshold: 0.0 ~ 1.0，返回 true 表示判定通过
  return _roll(seed) < threshold;
}

