  '中午': ['晚自习内容','深夜使用','上课'],
  '下午': ['睡眠春梦','深夜使用','晨读'],
  '傍晚': ['睡眠春梦','深夜使用','晨读','上课'],
  '晚自习': ['睡眠春梦','上午课间','午休'],
  '夜里': ['上课','课间','放学活动'],
  '半夜': ['上课','课间','放学活动','晚餐']
};

var slotMaxEvents = {
  '早晨': 2,
  '晨读': 2,
  '上午': 3,
  '中午': 2,
  '下午': 3,
  '傍晚': 2,
  '晚自习': 3,
  '夜里': 2,
  '半夜': 1
};

// ===== 考试节点判定（固定日期）=====
// 周三上午小考 / 月末3天月考 / 第30/60/90天季考 / 第103天高考 / 第120天成绩出炉
var examPeriod = '无';
var examInfo = '今日无考试';
if (day === 120) {
  examPeriod = '成绩出炉';
  examInfo = '高考成绩出炉日（第120天）- 触发终局分支判定';
} else if (day === 103) {
  examPeriod = '高考';
  examInfo = '高考日（第103天）- 决定结局走向的关键节点';
} else if (day === 30 || day === 60 || day === 90) {
  examPeriod = '季考';
  examInfo = '季考日（第' + day + '天）- 重要节点，影响学业阶段';
} else if (day % 30 >= 28) {
  examPeriod = '月考';
  examInfo = '月考日（每月最后3天：day%30>=28）';
} else if (day % 7 === 3) {
  examPeriod = '周考';
  examInfo = '周考（每周三：day%7===3）';
}

// ===== 距高考天数（高考在第103天）=====
var daysToGaokao = Math.max(0, 103 - day);

// ===== 时间轴阶段划分（总流程120天）=====
var timelinePhase;
if (day <= 30) timelinePhase = '初期（开学-第1月）';
else if (day <= 60) timelinePhase = '发展期（第2月）';
else if (day <= 95) timelinePhase = '中期（第3月-第4月初）';
else if (day <= 100) timelinePhase = '冲刺期（最后1月）';
else if (day <= 102) timelinePhase = '高考前夕（倒计时2天）';
else if (day === 103) timelinePhase = '高考日';
else if (day <= 120) timelinePhase = '结局期（成绩等待+终局判定）';
else timelinePhase = '终局';

var progressPct = Math.min(100, Math.round(day / 120 * 100));
_%>
<time_system>
【时间轴系统 - AI严格执行，严禁外露】

---
■ 当前时间
---
游戏日：第 <%= day %> 天/120
时段：<%= timeSlot %>（<%= slotRange %>）
当前hour：<%= hour %>
距离高考：<%= daysToGaokao %> 天
时间轴阶段：<%= timelinePhase %>
进度：<%= progressPct %>%

---
■ 本时段事件限制
---
当前时段：<%= timeSlot %>
允许事件类型：<%= (slotEvents[timeSlot] || []).join('、') %>
禁止事件类型：<%= (slotForbidden[timeSlot] || []).join('、') %>
本时段最大事件数：<%= slotMaxEvents[timeSlot] || 3 %>
下一时段：<%= nextSlot %>（需下一轮才能到达）

---
■ 每轮封顶铁律
---
- 本轮输出只能描述当前时段（<%= timeSlot %>）的事件
- 超过时段边界必须停止输出正文
- 即使玩家要求"快进""跳过数天""直接到周末"，也必须分多轮推进
- 时间推进由变量 AI 自动同步 时间.小时 字段控制
- 单轮 时间.小时 推进不得超过下一时段起点（详见下方推进表）
- 跨日推进（如夜间→次日早晨）需要 day+1

---
■ 小时连续性铁律（硬约束·不可省略）
---
- 时间必须连续推进，禁止跳跃。当前hour=<%= hour %>，下一轮只能推进到当前时段结束或下一时段起点
- 每轮推进幅度：同时段内推进1-2小时，或推进到下一时段的起始时刻
- 推进示例（合法）：
  · 上午09:50 → 上午11:30（同时段内推进1-2小时）
  · 上午09:50 → 中午12:00（推进到下一时段起点）
  · 上午11:30 → 中午12:30（推进到下一时段，并推进1小时）
- 推进示例（非法·必须修正）：
  · 上午09:50 → 中午13:00（跳过了上午剩余时间和中午起点，3小时跳跃）
  · 上午09:50 → 下午15:00（跳过了2个时段，5小时跳跃）
  · 上午09:50 → 第二天早晨07:00（跳过了整个白天和夜晚，跨日跳跃）
- 修正规则：若玩家指令隐含跳跃幅度过大，AI必须修正为合法推进幅度
  （如玩家说"继续上课，午休回宿舍"，但当前是9:50上午，AI应只推进到12:00中午起点，
   描写上午剩余课程，午休回宿舍留给下一轮）

---
■ 时段行为限制与超时终止（硬约束·不可省略）
---
- 每个时段只允许做该时段允许的事件（见上方 slotEvents）
- 禁止事件（slotForbidden）：如在"上午"时段尝试"午休事件" → 必须驳回
- **超时终止铁律**：玩家指令试图做的事情超出当前时段范围或无法在当前时段完成时，AI必须：
  ① 不跳时间、不废话、不延长时间
  ② 直接终止输出，告知玩家该行为无法在当前时段完成
  ③ 终止话术（必须原样输出核心内容）：
     "现在是<%= timeSlot %>（<%= slotRange %>），{玩家想做的事}不在此时段允许范围内。请等到{允许时段}再做。"
  ④ 示例：上午上课时玩家说"我去宿舍午休" → AI输出"现在是上午（08:00-12:00），午休不在此时段允许范围内。请等到中午（12:00-14:00）再做。"
  ⑤ 示例：中午时段玩家说"我上一整下午的课" → AI输出"现在是中午（12:00-14:00），上课不在此时段允许范围内。请等到下午（14:00-17:00）再做。"

---
■ 考试节点
---
<%= examInfo %>
<% if (examPeriod !== '无') { %>
考试期间修正：
- 女性 学业压力 +30（学业压力激增）
- 女性使用频率 × 0.6（female_use_freq 暂时降低）
- 考试结束日是使用反弹高发期（使用频率 × 1.5，持续1-2天）
- 考试日 hour 推进只在上午时段（08:00-12:00）
<% } else { %>
今日无考试修正。
<% } %>

---
■ 时间轴进度
---
进度：<%= progressPct %>%（第 <%= day %> 天/120 天）
当前阶段：<%= timelinePhase %>
使用阶段：<%= stage %>/5
难度：<%= difficulty %>

时间轴阶段说明：
- 初期（1-30天）：开学适应期，使用萌芽，第30天=第一次季考
- 发展期（31-60天）：第一次季考后，使用扩散，第60天=第二次季考
- 中期（61-95天）：第二次季考后，疯狂使用高发，第90天=第三次季考
- 冲刺期（96-100天）：学业压力攀升，使用与学业冲突加剧
- 高考前夕（101-102天）：最后冲刺，阶段4→5晋升窗口开启
- 高考日（103天）：第103天高考 - 决定结局走向的关键节点
- 结局期（104-120天）：高考完 → 第120天成绩出炉 → 终局判定

---
■ 9时段划分（高三学生时间表，每轮推进1个时段）
---
1. 早晨（05:00-07:00）：起床/洗漱/早餐/上学路上
2. 晨读（07:00-08:00）：早读/早自习/晨间小测
3. 上午（08:00-12:00）：上课/课间
4. 中午（12:00-14:00）：午餐/午休
5. 下午（14:00-17:00）：上课/课外活动
6. 傍晚（17:00-19:00）：晚餐/放学后活动
7. 晚自习（19:00-22:00）：晚自习/夜间预备
8. 夜里（22:00-02:00）：回宿舍/睡眠（使用高发期）
9. 半夜（02:00-05:00）：深度睡眠（使用最高发期）

---
■ 时间推进规则（变量 AI 自动写入）
---
当前时段 → 目标 hour 范围：
- 早晨（05-07）→ hour=7 进入晨读
- 晨读（07-08）→ hour=8 进入上午
- 上午（08-12）→ hour=12 进入中午
- 中午（12-14）→ hour=14 进入下午
- 下午（14-17）→ hour=17 进入傍晚
- 傍晚（17-19）→ hour=19 进入晚自习
- 晚自习（19-22）→ hour=22 进入夜里
- 夜里（22-02）→ hour=2 进入半夜（跨日，day+1）
- 半夜（02-05）→ hour=5 进入次日早晨（跨日，day+1）

跨日规则：
- 夜里→半夜：day+1, hour=2
- 半夜→次日早晨：day+1, hour=5
- 其他时段推进：day 不变，只改 hour

考试日特殊：
- 考试日（周考/月考/季考/高考）hour 必须在 08:00-12:00 之间停留
- 不允许跳过考试时段

---
■ AI 执行铁律
---
1. 每轮正文只描述当前时段（<%= timeSlot %>）的事件，超过时段边界立即停止
2. 严禁在正文中输出"时段""时间轴""进度""time_slot"等元术语
3. 严禁在玩家要求"快进"时跨时段推进——必须分多轮
4. 考试日必须在叙事中体现（如"今天是周考日""下午有月考"）
5. 高考日（第103天）和成绩出炉日（第120天）是固定剧情节点，不可跳过
6. 每轮变量 AI 自动写入 时间.小时 和 时间.时段 变化
7. 命中考试节点时，必须写入 时间.考试周期 字段
8. 跨日推进必须写入 时间.天数 和 时间.学期天数 同时+1
9. 距高考天数 字段 = max(0, 103 - day)，AI 必须同步更新
</time_system>

