}

// ===== 时段判定（与时间轴系统对齐）=====
var timeSlot;
if (hour >= 5 && hour < 7) timeSlot = '早晨';
else if (hour >= 7 && hour < 8) timeSlot = '晨读';
else if (hour >= 8 && hour < 12) timeSlot = '上午';
else if (hour >= 12 && hour < 14) timeSlot = '中午';
else if (hour >= 14 && hour < 17) timeSlot = '下午';
else if (hour >= 17 && hour < 19) timeSlot = '傍晚';
else if (hour >= 19 && hour < 22) timeSlot = '晚自习';
else if (hour >= 22 || hour < 2) timeSlot = '夜里';
else timeSlot = '半夜';

// ===== 天气时段修正 =====
// 2月开学，温度5-15℃，湿度50-80%
// 多云/晴/阴/小雨/中雨/大雨/雪/雾
var weatherEffects = {
  '晴': { mood:'+5', energy:'+2', suspicion_perception:'+0' },
  '多云': { mood:'+0', energy:'+0', suspicion_perception:'+0' },
  '阴': { mood:'-3', energy:'-2', suspicion_perception:'+1' },
  '小雨': { mood:'-5', energy:'-3', suspicion_perception:'+2', restrict:'户外活动受限' },
  '中雨': { mood:'-8', energy:'-5', suspicion_perception:'+3', restrict:'户外活动禁止' },
  '大雨': { mood:'-10', energy:'-8', suspicion_perception:'+5', restrict:'户外活动禁止，能见度低' },
  '雪': { mood:'+2', energy:'-5', suspicion_perception:'+2', restrict:'路面结冰' },
  '雾': { mood:'-3', energy:'-2', suspicion_perception:'+5', restrict:'能见度极低，雷达范围-30%' }
};

var curWeatherEffect = weatherEffects[weather] || weatherEffects['多云'];
%>

<environment_system>
【RPG环境系统 - AI内部参考，严禁外露元数据】

---
■ 当前环境状态
---
日期：第 <%= day %> 天（<%= dateStr %>，星期<%= ['一','二','三','四','五','六','日'][weekday-1] %>）
时段：<%= timeSlot %>（hour=<%= hour %>）
当前位置：<%= currentLocation %>（区域：<%= currentZone %>）
季节：<%= season %>
天气：<%= weather %> | 温度：<%= temperature %>℃ | 湿度：<%= humidity %>%

天气效果：
- 心情修正：<%= curWeatherEffect.mood %>
- 精力修正：<%= curWeatherEffect.energy %>
- 感知修正：<%= curWeatherEffect.suspicion_perception %>
<% if (curWeatherEffect.restrict) { %>- 活动限制：<%= curWeatherEffect.restrict %><% } %>

---
■ 校园区域与位置
---
<% zones.forEach(function(z) { %>
【<%= z.id %>】<%= z.locations.join('、') %>
<% }); %>

位置切换规则：
- 相邻区域移动：1时段（如教学楼→食堂，需消耗1时段）
- 同区域内移动：不消耗时段（如高三2班教室→走廊→卫生间）
- 跨校区移动：禁止（封闭管理）
- 时段限制位置：
  · 宿舍：仅夜里(22:00后)和早晨(05:00-07:00)可进入
  · 教学楼：晨读-晚自习(07:00-22:00)可进入
  · 食堂：早晨/中午/傍晚三餐时段可进
  · 校医室：上午-傍晚(08:00-19:00)可进，需沈雨桐在场才能买药
  · 图书馆：中午/傍晚/晚自习可进
  · 操场：早晨/下午/傍晚可进
- {{user}}位置移动由变量 AI 自动 patch：
  - stat_data.环境.位置 = 新位置
  - stat_data.环境.区域 = 新区域

---
■ 活动倒计时系统
---
<% activities.forEach(function(a) { %>
- <%= a.name %>：倒计时 <%= a.countdown %> 天 | 重要性：<%= a.importance %> | <%= a.desc %>
<% }); %>

活动推进规则：
- 每跨日（day+1）所有倒计时-1
- 倒计时归零当日触发对应活动
- 周考/月考触发后自动重置下一周期倒计时
- 活动触发由变量 AI 自动同步：
  - stat_data.环境.活动.<activity_id>.countdown = 新值
  - stat_data.环境.活动.<activity_id>.last_triggered_day = day

---
■ 新闻系统
---
当前新闻列表（按热度排序）：
<% newsList.sort(function(a,b){return (b.热度||0) - (a.热度||0);}).slice(0,5).forEach(function(n) { %>
- [<%= n.头条 || '未知' %>] <%= n.内容 || '' %>（热度:<%= n.热度 || 0 %> 重要性:<%= n.重要性 || 0 %>% 来源:<%= n.来源 || '未知' %> <%= n.时间 || '' %>）
<% }); %>

新闻类型与机制：
- 公告（credibility=100%）：教务处/校长室/广播站发布的官方通知
- 八卦（credibility=30-70%）：学生间传播的传言，热度衰减慢但可信度低
- 社会（credibility=80-100%）：电视台/报纸/网络新闻，与校园间接相关
- 紧急（credibility=90%+）：突发事件通知，热度峰值高、衰减极快

新闻生成规则：
- 每天最多生成1-2条新新闻
- 八卦热度初始值50-80，每天-10
- 公告热度初始值30-50，每天-5
- 紧急新闻热度初始值90+，每天-20
- 八卦可信度受事件真实性影响：真事件70%+，假事件<40%
- 玩家行为可能成为新闻源（如被发现异常行为 → 八卦热度暴涨）
- 重大剧情节点必须生成对应新闻（如考试作弊传闻、女生失踪等）

新闻存储字段：
- stat_data.环境.新闻 = record<string, EnvNewsSchema>，key 为新闻编号
- 每条新闻字段：编号/标题/头条/热度/重要性/内容/摘要/来源/时间/位置/状态
- 编号 news001 起递增，稳定不重用
- 已生成新闻保留 7 天后自动清理

---
■ 环境状态更新铁律
---
1. 每轮必须更新环境状态（除非本轮未发生时段变化/移动/天气变化）：
   - 时段变化 → 更新 timeSlot 描述、调整活动可用性
   - 位置移动 → 更新 location/zone，并触发新位置的雷达扫描
   - 跨日 → 重新生成天气、调整温度湿度、所有活动倒计时-1
2. 天气系统跨日更新规则：
   - 季节基准温度：2-3月 5-15℃ / 4-5月 15-25℃ / 6月 25-32℃
   - 天气随机切换概率：晴20% / 多云30% / 阴20% / 雨20% / 雾雪10%
   - 连续3天同天气后必切换
   - 雨天持续不超过2天，雪天持续不超过3天
3. 每轮环境状态变化由变量 AI 自动同步：
   - stat_data.环境.天气 = 新天气
   - stat_data.环境.温度 = 新温度
   - stat_data.环境.湿度 = 新湿度
   - stat_data.环境.位置 = 新位置（如移动）
   - stat_data.环境.区域 = 新区域（如移动）
4. 严禁正文出现"环境系统""天气效果""雷达范围-30%"等元术语
5. 天气对叙事的转化：
   - 阴雨天 {{user}} 心情低落、精力恢复变慢、女性使用频率可能微升（独自室内时间增多）
   - 雾天 {{user}} 感知异常度上升（"今早起床雾气很重，走廊里什么都看不清"）
   - 晴天 {{user}} 心情转好、户外活动增多、女性户外活动也增多
6. 新闻与剧情联动：
   - 重大事件发生次日生成对应新闻（如某女学生请假多日 → 八卦）
   - 新闻可作为线索触发 {{user}} 调查动机
   - 假新闻（credibility<40）可能误导 {{user}} 判断
7. 活动倒计时归零当日 AI 必须在叙事中体现：
   - 周考日：上午时段固定描述考试场景
   - 月考日：连续3天考试场景
   - 升旗日：周一早晨固定描述
   - 体育课日：周五下午固定描述
</environment_system>

@@generate_before
<%
// [mvu_plot]多维状态每日演化
// 每日游戏日开始时执行：应用每日判定、周期事件，重新计算 综合阶段
// 输出 <multi_stage_update> 块给 AI（仅行为侧写，不输出数值）
// 参考飞机杯 uid=10 EJS 控制器模式 + [mvu_plot]每日重置.txt 的 isNewDay 判定

var day = Number(getvar('stat_data.时间.天数', {scope:'local', defaults:1})) || 1;
var hour = Number(getvar('stat_data.时间.小时', {scope:'local', defaults:8})) || 8;
var prevDayKey = '多维状态上一日';
var prevDay = Number(getvar('stat_data.隐藏层.' + prevDayKey, {scope:'local', defaults:0})) || 0;
// 首次加载时初始化 prevDay，防止误触发
if (prevDay === 0) { setvar('stat_data.隐藏层.' + prevDayKey, day); }
var isNewDay = hour === 0 && day !== prevDay && prevDay !== 0;

// 周期判定（day 从 1 开始）
// day % 7 == 1 → 周一（学业压力 += 10）
// day % 7 == 0 || day % 7 == 6 → 周末（学业压力 -= 15）
// day % 30 == 0 → 考试周（学业压力 += 30）
var dow = day % 7;
var cycleEvent = '无';
if (day % 30 === 0) {
  cycleEvent = '考试周（学业压力 +30）';
} else if (dow === 1) {
  cycleEvent = '周一（学业压力 +10）';
} else if (dow === 0 || dow === 6) {
  cycleEvent = '周末（学业压力 -15）';
}

// ============================================================
// 综合阶段 判定函数（返回组合值字符串，用于显示）
// ============================================================
// A_理性期: 理性>=70 且 执念<30
// B_动摇期: 理性 50-70 或 执念 30-50
// C_沉沦期: 理性 30-50 或 执念 50-70
// D_疯狂期: 理性<30 且 执念>70
// E_清醒反扑期: 逃避意识>60（临时，可叠加在A-D上）
function _computeStage(ms) {
  var r = Number(ms.理性) || 0;
  var o = Number(ms.执念) || 0;
  var e = Number(ms.逃避意识) || 0;
  if (e > 60) {
    // 清醒反扑期可叠加
    if (r < 30 && o > 70) return 'D_疯狂期+E_清醒反扑期';
    if (r >= 70 && o < 30) return 'A_理性期+E_清醒反扑期';
    return 'E_清醒反扑期';
  }
  if (r >= 70 && o < 30) return 'A_理性期';
  if (r < 30 && o > 70) return 'D_疯狂期';
  if (r < 10 || o >= 90) return 'E_崩坏期';
  if (r < 50 || o > 50) return 'C_沉沦期';
  return 'B_动摇期';
}

// 把组合值映射到 schema enum 允许的值（综合阶段 字段类型为 enum）
// enum: ['A_理性期','B_动摇期','C_沉沦期','D_疯狂期','E_清醒反扑期']
function _mapToEnumStage(compositeStr) {
  if (compositeStr === 'D_疯狂期+E_清醒反扑期') return 'D_疯狂期';
  if (compositeStr === 'A_理性期+E_清醒反扑期') return 'E_清醒反扑期';
  return compositeStr; // A_理性期 / B_动摇期 / C_沉沦期 / D_疯狂期 / E_清醒反扑期
}

// 行为侧写映射（AI 叙事转化，不输出数值）
function _behaviorProfile(stage) {
  if (stage === 'D_疯狂期+E_清醒反扑期') return '疯狂使用后崩溃大哭；反复藏起又取出；精神状态极不稳定';
  if (stage === 'A_理性期+E_清醒反扑期') return '表面正常但内心挣扎；把假阴茎藏起来；独自哭泣；写日记自责';
  if (stage === 'E_清醒反扑期') return '把假阴茎藏起来；试图还给持有者；独自哭泣；写日记自责';
  if (stage === 'A_理性期') return '表现得和往常一样，上课、社交、微笑，看不出任何异常';
  if (stage === 'B_动摇期') return '偶尔走神，眼神会有几秒的空洞，但很快恢复；独处时会不自觉握紧手心';
  if (stage === 'C_沉沦期') return '开始找理由独处；书包里多了换洗内裤；午休时间消失；眼神涣散频率增加';
  if (stage === 'D_疯狂期') return '不顾风险在课间使用；眼神痴迷；对任何人的靠近反应过度（恐惧或讨好），对{{user}}只是表层伪装';
  return '状态不明';
}

// 读取所有女性
var femaleUsers = getvar('stat_data.女性角色', {scope:'local', defaults:{}}) || {};
var uidOrder = femaleUsers.UID顺序 || [];
var updates = [];

if (isNewDay) {
  setvar('stat_data.隐藏层.' + prevDayKey, day);

  // 遍历所有女性，应用每日判定和周期事件
  uidOrder.forEach(function(uid) {
    var fu = femaleUsers[uid];
    if (!fu || !fu.多维状态) return;

    var ms = Object.assign({}, fu.多维状态 || {});
    var changed = false;

    // 1. 周期事件：学业压力 调整
    if (day % 30 === 0) {
      ms.学业压力 = Math.min(100, Math.max(0, (ms.学业压力 || 0) + 30));
      changed = true;
    } else if (dow === 1) {
      ms.学业压力 = Math.min(100, Math.max(0, (ms.学业压力 || 0) + 10));
      changed = true;
    } else if (dow === 0 || dow === 6) {
      ms.学业压力 = Math.min(100, Math.max(0, (ms.学业压力 || 0) - 15));
      changed = true;
    }

    // 2. 每日判定
    // if 学业压力 > 80: 逃避意识 += 5（清醒的压力压制了痴迷）
    if ((ms.学业压力 || 0) > 80) {
      ms.逃避意识 = Math.min(100, Math.max(0, (ms.逃避意识 || 0) + 5));
      changed = true;
    }
    // if 逃避意识 > 60: 理性 += 3, 执念 -= 2（清醒反扑期持续 3-7 天）
    if ((ms.逃避意识 || 0) > 60) {
      ms.理性 = Math.min(100, Math.max(0, (ms.理性 || 80) + 3));
      ms.执念 = Math.min(100, Math.max(0, (ms.执念 || 0) - 2));
      changed = true;
    }
    // if 理性 < 30 && 执念 > 70: 暴露风险 +10%（由 AI 在叙事中体现，不在此处加变量）

    // 3. 重新计算 综合阶段
    var compositeStr = _computeStage(ms);
    var enumStage = _mapToEnumStage(compositeStr);
    if (ms.综合阶段 !== enumStage) {
      ms.综合阶段 = enumStage;
      changed = true;
    }

    // 4. 写回变量（仅当有变化时）
    if (changed) {
      setvar('stat_data.女性角色.' + uid + '.多维状态', ms, {scope:'local'});
    }

    // 5. 收集更新信息（用于输出块）
    var name = (fu.基础 && fu.基础.姓名) ? fu.基础.姓名 : uid;
    updates.push({
      uid: uid,
      name: name,
      stage: compositeStr,
      profile: _behaviorProfile(compositeStr),
    });
  });
} else {
  // 非新一天，仍然收集当前状态用于输出（不修改变量）
  uidOrder.forEach(function(uid) {
    var fu = femaleUsers[uid];
    if (!fu || !fu.多维状态) return;
    var ms = fu.多维状态;
    var compositeStr = _computeStage(ms);
    var name = (fu.基础 && fu.基础.姓名) ? fu.基础.姓名 : uid;
    updates.push({
      uid: uid,
      name: name,
      stage: compositeStr,
      profile: _behaviorProfile(compositeStr),
    });
  });
}
%>
<multi_stage_update>
[多维状态每日演化 - AI内部参考，严禁输出数值]

<% if (isNewDay) { %>
=== 跨天触发：进入新的一天（第<%= day %>天），已应用每日判定和周期事件 ===
今日周期事件：<%= cycleEvent %>
<% } else { %>
=== 等待跨天触发（当前 hour=<%= hour %>，跨天需 hour 从 23→0） ===
今日周期事件（待触发）：<%= cycleEvent %>
<% } %>

各活跃女性行为侧写（共 <%= updates.length %> 人）：
<% updates.forEach(function(u) { %>- <%= u.name %>(<%= u.uid %>): <%= u.stage %> → <%= u.profile %>
<% }); %>

[行为侧写参考]
A_理性期: 表现正常
B_动摇期: 偶尔走神
C_沉沦期: 主动找机会使用
D_疯狂期: 不顾风险
E_清醒反扑期: 想戒掉、藏起来
D+E: 疯狂使用后崩溃
A+E: 表面正常但内心挣扎

[信息隔离铁律重申]
- {{user}} 永远看不到这些数值和阶段标签
- AI 只能通过"行为侧写"感知女性状态，不得直接读取数值到正文
- 严禁在正文中出现 理性/执念/痴迷度/理性值 等元数值术语
- 严禁在正文中出现 A_理性期/B_动摇期 等阶段标签，只能用行为侧写表达
- 女性之间的多维状态互相隔离（A 不知道 B 的痴迷程度）
</multi_stage_update>
